        IRValue raw_idx = -1, other = -1;
        int sc = -1;
        if (gep_scaled_index(fn, def, d->a, &raw_idx, &sc))
            other = d->b;
        else if (gep_scaled_index(fn, def, d->b, &raw_idx, &sc))
            other = d->a;
